import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Base64InputStream_read_TriageGen1Test {

















    @Test
    public void testRead_Decode_NoData_OptimizationTriggered() throws IOException {
        // Use a small buffer to trigger the !base64.hasData() block
        // and test the optimization: if (c > 0 && b.length == len)
        byte[] input = "SGVsbG8=".getBytes();
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(input), false);

        // Force the optimization branch: b.length == len
        byte[] b = new byte[5];
        bis.read(b, 0, 5);
    }




}

package org.apache.commons.codec.binary;

