import static org.junit.Assert.assertEquals;

public class Base64InputStream_read_TriageGen1Test {



















    @Test
    public void testRead_Encode_NoData_NoOptimization() throws IOException {
        // Test the encode branch where b.length != len
        byte[] input = "Hello".getBytes();
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(input), true);

        byte[] b = new byte[10];
        bis.read(b, 0, 5); // len is 5, b.length is 10 -> optimization skipped
    }


}

